import { processActiveTurn } from './runtime-turn.mjs';
const HEX40=/^[a-f0-9]{40}$/,HEX64=/^[a-f0-9]{64}$/;
function gitBlobSha1(bytes){const b=Buffer.isBuffer(bytes)?bytes:Buffer.from(bytes);return crypto.createHash('sha1').update(Buffer.from(`blob ${b.length}\\0`)).update(b).digest('hex');}
function loadBootstrap(){return JSON.parse(fs.readFileSync(path.join(ROOT,'BOOTSTRAP.json'),'utf8'));}
function transferMaterial(t){return{schema:t?.schema,source_head:t?.source_head,transport:t?.transport,exact_ref:t?.exact_ref,complete:t?.complete,fallback_used:t?.fallback_used,model_reconstruction:t?.model_reconstruction,remote_rounds:t?.remote_rounds,remote_reads:t?.remote_reads,remote_paths_sha256:t?.remote_paths_sha256,runtime_root_sha256:t?.runtime_root_sha256,loader_blob_sha1:t?.loader_blob_sha1,authority:t?.authority};}
function materializationMaterial(r){return{schema:r?.schema,source_head:r?.source_head,runtime_root_sha256:r?.runtime_root_sha256,loader_blob_sha1:r?.loader_blob_sha1,member_count:r?.member_count,source_bytes:r?.source_bytes,shard_count:r?.shard_count,reused_orientation_paths:r?.reused_orientation_paths,atomic_publish:r?.atomic_publish,reopen_verified:r?.reopen_verified,authority:r?.authority};}
function evidenceMaterial(e){return{schema:e?.schema,source_head:e?.source_head,accepted_to_materialized_ms:e?.accepted_to_materialized_ms,monotonic:e?.monotonic,transfer_receipt_sha256:e?.transfer_receipt_sha256,materialization_receipt_sha256:e?.materialization_receipt_sha256,authority:e?.authority};}
function digestObject(x){return sha256(Buffer.from(JSON.stringify(x)));}
function currentRuntimeRootMatches(d){try{const loader=fs.readFileSync(path.join(ROOT,d.loader.path));if(gitBlobSha1(loader)!==d.loader.blob_sha1)return false;for(const x of d.members){const bytes=fs.readFileSync(path.join(ROOT,x.path));if(bytes.length!==x.bytes||gitBlobSha1(bytes)!==x.blob_sha1)return false;}return true;}catch{return false;}}
function validateBootstrapEvidence(e,sourceHead){const b=loadBootstrap(),f=b.post_accept_fastboot,d=f?.runtime_root,h=readHostShell(),t=e?.transfer,m=e?.materialization;if(!e||e.schema!=='ikant-le-bootstrap-evidence/v1')return{ok:false,code:'EVIDENCE_SCHEMA'};if(!HEX40.test(String(sourceHead||''))||e.source_head!==sourceHead)return{ok:false,code:'EVIDENCE_SOURCE'};if(e.monotonic!==true||!Number.isFinite(e.accepted_to_materialized_ms)||e.accepted_to_materialized_ms<0)return{ok:false,code:'EVIDENCE_CLOCK'};if(h.fastboot?.loader!==d?.loader?.path||h.fastboot?.deadline_ms!==f?.deadline_ms||h.fastboot?.max_post_accept_remote_reads!==f?.max_post_accept_remote_reads)return{ok:false,code:'CONTRACT_DRIFT'};const pathsDigest=digestObject(f.remote_paths),tm=transferMaterial(t);if(!t||t.schema!=='ikant-le-source-bound-transfer/v1'||t.source_head!==sourceHead||t.transport!=='GITHUB_API'||t.exact_ref!==true||t.complete!==true||t.fallback_used!==false||t.model_reconstruction!==false||t.authority!==0||!Number.isInteger(t.remote_rounds)||t.remote_rounds<1||t.remote_rounds>f.remote_acquisition_rounds_max||!Number.isInteger(t.remote_reads)||t.remote_reads<1||t.remote_reads>f.max_post_accept_remote_reads||t.remote_paths_sha256!==pathsDigest||t.runtime_root_sha256!==d.runtime_root_sha256||t.loader_blob_sha1!==d.loader.blob_sha1||!HEX64.test(String(t.receipt_sha256||''))||digestObject(tm)!==t.receipt_sha256)return{ok:false,code:'TRANSFER_RECEIPT'};const mm=materializationMaterial(m);if(!m||m.schema!=='ikant-le-runtime-root-materialization/v1'||m.source_head!==sourceHead||m.runtime_root_sha256!==d.runtime_root_sha256||m.loader_blob_sha1!==d.loader.blob_sha1||m.member_count!==d.member_count||m.source_bytes!==d.source_bytes||m.shard_count!==d.shards.length||m.atomic_publish!==true||m.reopen_verified!==true||m.authority!==0||!HEX64.test(String(m.receipt_sha256||''))||digestObject(mm)!==m.receipt_sha256)return{ok:false,code:'MATERIALIZATION_RECEIPT'};if(e.transfer_receipt_sha256!==t.receipt_sha256||e.materialization_receipt_sha256!==m.receipt_sha256||e.authority!==0||!HEX64.test(String(e.receipt_sha256||''))||digestObject(evidenceMaterial(e))!==e.receipt_sha256)return{ok:false,code:'EVIDENCE_RECEIPT'};if(!currentRuntimeRootMatches(d))return{ok:false,code:'CURRENT_RUNTIME_ROOT'};if(e.accepted_to_materialized_ms>f.deadline_ms)return{ok:false,code:'BOOTSTRAP_DEADLINE_EXCEEDED'};return{ok:true,deadline_ms:f.deadline_ms,remote_elapsed_ms:e.accepted_to_materialized_ms,bindings:{source_head:sourceHead,runtime_root_sha256:d.runtime_root_sha256,transfer_receipt_sha256:t.receipt_sha256,materialization_receipt_sha256:m.receipt_sha256,evidence_receipt_sha256:e.receipt_sha256,deadline_ok:true,elapsed_ms:e.accepted_to_materialized_ms}};}
function bootstrapReceipt(state,termsDigest,fingerprint,probe,hostEngine,hostSurface,terminal,mode){const material={schema:'ikant-le-bootstrap-receipt/v3',epoch:state.epoch,terms_digest:termsDigest,constitutional_fingerprint:fingerprint,source_head:state.bootstrap?.source_head||null,runtime_root_sha256:state.bootstrap?.runtime_root_sha256||null,transfer_receipt_sha256:state.bootstrap?.transfer_receipt_sha256||null,materialization_receipt_sha256:state.bootstrap?.materialization_receipt_sha256||null,evidence_receipt_sha256:state.bootstrap?.evidence_receipt_sha256||null,deadline_ok:state.bootstrap?.deadline_ok===true,elapsed_ms:Number.isFinite(state.bootstrap?.elapsed_ms)?state.bootstrap.elapsed_ms:null,host_profile:{surface:hostSurface,engine:hostEngine},probe:{ok:Boolean(probe?.ok),node:probe?.node||null,fs:probe?.fs||null,crypto:probe?.crypto||null,clock:probe?.clock||null,artifact_sink:Boolean(probe?.artifact_sink),warm:Boolean(probe?.warm)},mode,terminal,host_constraints_precede_local_contract:true};return{...material,receipt_sha256:sha256(Buffer.from(JSON.stringify(material)))};}
function recordNodeDispatch(state,input,hostSurface){const receipt=nodeDispatchReceiptPure(input,state,{hostSurface});const s=structuredClone(state);s.admission.last_node_dispatch_receipt=receipt.receipt_sha256;appendEvent('NODE_DISPATCH',s,'Human input entered the local Node runtime before any iKant response path.',{receipt});return{s,receipt};}
function human(text,code=0){return{stdout:text,code};}
function bootstrapOnlyPendingIntent(input){const init=new Set(['inizializza','inizializzazione','initialize','initialise','avvia','attiva','bootstrap']),env=new Set(['ambiente','runtime','ikant','ikant_le','sessione','session','locale','local','controllata','controlled']),structural=new Set(['il','lo','la','i','gli','le','un','una','di','del','della','per','e','and','the','a','an','please','pls','repo','repository']);const raw=String(input??'').normalize('NFKC').toLowerCase().replace(/https?:\/\/github\.com\/luke883i\/ikant_le(?:\.git)?/g,' ikant_le ').replace(/[^\p{L}\p{N}_]+/gu,' ').trim(),words=raw.split(/\s+/).filter(Boolean);return words.length>0&&words.some(w=>init.has(w))&&words.filter(w=>!init.has(w)&&!env.has(w)&&!structural.has(w)).length===0;}
function termsMessage(terms){return`${terms.text.trim()}\n\nTerms digest: ${terms.digest}\n\nSe accetti questi termini nella sessione corrente, rispondi esattamente: I ACCEPT`;}
export function runCommand(input,{candidate=null,hostEngine='motore host non dichiarato',hostSurface='LOCAL_NODE_CHAT_HOST',resourceGrants=[],probeRunner=runProbe,hostAcquisition=[],hostObservations=[],actionReceipt=null,postActionObservations=[],preacceptHandoff=null,bootstrapEvidence=null,monotonicNow=()=>performance.now()}={}){return withWriterLock(()=>{const terms=readTerms();const fingerprint=constitutionalFingerprint();let state=loadState();const kind=classifyInput(input);if(preacceptHandoff&&kind!=='ACCEPT')return human('Il pre-accept handoff può essere importato solo insieme allo stesso messaggio umano esatto I ACCEPT.',1);if(kind==='ACCEPT'&&preacceptHandoff){const imported=importPreacceptHandoff(state,preacceptHandoff,terms.digest);if(!imported.ok)return human(`Il pre-accept handoff non è valido (${imported.code}); iKant resta non-ACTIVE.`,1);state=imported.state;appendEvent('PREACCEPT_HANDOFF',state,'Host-observed pre-accept context imported into fresh local state without promoting acceptance, probe or initialization.',{handoff_sha256:imported.digest,source_head:imported.source_head,runtime_observed_terms_presentation:false,host_attested_terms_presentation:true,authority:0});}let dispatched=recordNodeDispatch(state,input,hostSurface);state=dispatched.s;const dispatch=dispatched.receipt;if(!dispatch.node20_plus)return human('L’ambiente corrente non dimostra Node.js 20 o superiore; iKant resta non-ACTIVE.',1);
for(const evt of hostAcquisition){if(state.accepted)break;if(evt.completed){const breach=recordCompletedPreacceptAccess(state,evt.action,{target:evt.target});if(breach.breached){state=breach.state;appendEvent('CAPSULE_BREACH',state,'Forbidden pre-accept repository acquisition completed; this chat cannot become a conforming iKant session.',{action:evt.action,target:evt.target||null});return human('Questa chat ha oltrepassato la capsula di orientamento prima dell’accettazione. Non posso sanarla retroattivamente come sessione iKant conforme: apri una nuova chat e inizializzala dal link canonico del repository.',1);}}else{const d=authorizePreaccept(state,evt.action,{target:evt.target,byteCount:evt.byteCount||0,metadataFields:evt.metadataFields||[]});if(!d.allowed)return human('La richiesta di acquisizione pre-accept è fuori dalla capsula consentita; il bootstrap resta fermo.',1);state=d.state;appendEvent('ORIENTATION',state,'Bounded pre-accept orientation operation allowed by capsule.',{action:evt.action,target:evt.target||null});}}
if(state.admission.breached||state.status==='SESSION_NONCONFORMING')return human('Questa chat è marcata non conforme per una rottura pre-accept della capsula. Per una sessione iKant conforme è necessaria una nuova chat.',1);
if(kind==='TERMS'){state=presentTermsState(state,terms.digest);appendEvent('TERMS_PRESENTED',state,'Current Terms were presented and pre-accept repository acquisition is now frozen.',{terms_digest:terms.digest});return human(termsMessage(terms));}
if(kind==='ACCEPT'){if(!canAccept(state,terms.digest))return human('L’accettazione non è valida finché i Terms correnti non sono stati presentati e legati a questa sessione. Chiedi TERMS o formula la tua richiesta: conserverò l’intento e mostrerò i Terms.',1);const next=transitionPure(state,kind,terms.digest);if(next.terminal==='DENY')return human('L’ammissione non può essere riaperta in questo stato.',1);next.state.epoch=newEpoch();const ev=validateBootstrapEvidence(bootstrapEvidence,state.admission.source_head),sourceHead=state.admission.source_head||null,root=ev.ok?ev.bindings.runtime_root_sha256:null,mode=bootstrapMode(state,fingerprint,{sourceHead,runtimeRootSha256:root});if(ev.ok)next.state.bootstrap={...next.state.bootstrap,...ev.bindings,mode,fingerprint,terminal:'ACCEPTED'};else next.state.bootstrap={...next.state.bootstrap,mode,fingerprint,terminal:'FAILURE',source_head:sourceHead};appendEvent('ACCEPT',next.state,'Exact current-session Terms acceptance bound; automatic bootstrap authorized.',{bootstrap_mode:mode,preaccept_handoff_sha256:state.admission.preaccept_handoff_sha256||null,source_head:sourceHead,evidence_receipt_sha256:ev.ok?ev.bindings.evidence_receipt_sha256:null});if(!ev.ok){const receipt=bootstrapReceipt(next.state,terms.digest,fingerprint,null,hostEngine,hostSurface,ev.code==='BOOTSTRAP_DEADLINE_EXCEEDED'?'BOOTSTRAP_DEADLINE_EXCEEDED':'FAILURE',mode);next.state.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('BOOTSTRAP_FAILURE',next.state,'Post-accept source transfer/materialization evidence did not satisfy the ACTIVE gate.',{code:ev.code,receipt});return human('Non posso dichiararmi attivo: il trasferimento o la materializzazione post-accept non sono stati verificati end-to-end. La sessione resta non-ACTIVE.',1);}const localStart=Number(monotonicNow()),probe=probeRunner({warm:mode==='WARM',hostSurface}),localElapsed=Math.max(0,Number(monotonicNow())-localStart),totalElapsed=ev.remote_elapsed_ms+localElapsed;next.state.bootstrap.elapsed_ms=totalElapsed;next.state.bootstrap.deadline_ok=Number.isFinite(totalElapsed)&&totalElapsed<=ev.deadline_ms;if(!next.state.bootstrap.deadline_ok){next.state.status='FAILURE';next.state.bootstrap.terminal='BOOTSTRAP_DEADLINE_EXCEEDED';const receipt=bootstrapReceipt(next.state,terms.digest,fingerprint,probe,hostEngine,hostSurface,'BOOTSTRAP_DEADLINE_EXCEEDED',mode);next.state.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('BOOTSTRAP_FAILURE',next.state,'The end-to-end post-accept deadline expired before ACTIVE commit.',{deadline_ms:ev.deadline_ms,elapsed_ms:totalElapsed,receipt});return human('Il bootstrap ha superato il limite end-to-end di 120 secondi; iKant resta non-ACTIVE.',1);}const decision=bootstrapDecisionPure(next.state,terms.digest,fingerprint,probe,{hostSurface,hostEngine});if(decision.terminal!=='ACTIVE'){const receipt=bootstrapReceipt(decision.state,terms.digest,fingerprint,probe,hostEngine,hostSurface,decision.terminal,mode);decision.state.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('BOOTSTRAP_FAILURE',decision.state,'Automatic post-accept bootstrap did not reach ACTIVE; no false activation permitted.',{receipt});return human('Non posso dichiararmi attivo: una verifica necessaria del bootstrap non è stata superata. La sessione resta non-ACTIVE.',1);}let probed=transitionPure(next.state,'PROBE',terms.digest,true).state;probed.bootstrap={...decision.state.bootstrap,terminal:'PROBED'};appendEvent('PROBE',probed,'Automatic local Node probe passed with real readback.',{node:probe.node,fs:probe.fs,warm:mode==='WARM',host_surface:hostSurface,elapsed_ms:totalElapsed});let active=transitionPure(probed,'INITIALIZE',terms.digest).state;const receipt=bootstrapReceipt(active,terms.digest,fingerprint,probe,hostEngine,hostSurface,'ACTIVE',mode);active.bootstrap={...decision.state.bootstrap,terminal:'ACTIVE',last_receipt_sha256:receipt.receipt_sha256};appendEvent('INITIALIZE',active,'Automatic iKant epoch initialization completed after source-bound transfer, verified local root, live probe and receipt-gated commit.',{receipt});const pending=active.admission.pending_intent;if(pending){active.admission.pending_intent=null;if(bootstrapOnlyPendingIntent(pending)){appendEvent('PENDING_INTENT_FULFILLED_BY_ACTIVE',active,'The preserved request was pure bootstrap control and is satisfied by the ACTIVE transition without creating a synthetic substantive turn.',{pending_intent_sha256:active.admission.pending_intent_sha256,authority:0});return human('iKant è attivo. L’intento di inizializzazione è stato soddisfatto dalla transizione ACTIVE; non viene creato un turno cognitivo artificiale.');}appendEvent('PENDING_INTENT_RESUME',active,'The original substantive request is resumed automatically after successful admission.',{pending_intent_sha256:active.admission.pending_intent_sha256});const pd=recordNodeDispatch(active,pending,hostSurface);return processActiveTurn(pd.s,pending,{candidate,hostEngine,resourceGrants,hostObservations,actionReceipt,postActionObservations},terms,pd.receipt,{resumed:true}).out;}return human('iKant è attivo. La shell narrativa è pronta; ogni prossimo input passerà dal runtime Node e il dettaglio tecnico resterà nel backlog DOCX.');}
if(kind==='PROBE'){if(state.status==='ACTIVE')return human('Il probe automatico di questa epoch risulta già superato; nessun nuovo gate è necessario.');const probe=probeRunner({warm:false,hostSurface});const next=transitionPure(state,kind,terms.digest,probe.ok);if(next.terminal==='DENY')return human('Probe diagnostico negato: serve prima una accettazione valida dei Terms correnti.');if(next.terminal==='HOST_INCOMPATIBLE'){appendEvent('PROBE_FAILURE',next.state,'Diagnostic probe failed; iKant remains non-ACTIVE.',{reason:probe.reason});return human('Il probe diagnostico non è stato superato; iKant resta non-ACTIVE.',1);}next.state.bootstrap={...next.state.bootstrap,probe,terminal:'PROBED'};appendEvent('PROBE',next.state,'Diagnostic recovery probe passed.',{node:probe.node});return human('Probe diagnostico superato. Se questa è una recovery manuale, INITIALIZE IKANT può completare l’epoch.');}
if(kind==='INITIALIZE'){if(state.status==='ACTIVE')return human('L’inizializzazione automatica di questa epoch risulta già completata.');const next=transitionPure(state,kind,terms.digest);if(next.terminal==='DENY')return human('Inizializzazione diagnostica negata: accettazione e probe correnti devono risultare validi.');next.state.bootstrap={...next.state.bootstrap,terminal:'ACTIVE',fingerprint};appendEvent('INITIALIZE',next.state,'Diagnostic recovery initialization completed.');return human('iKant è attivo.');}
if(kind==='EXIT'){const next=transitionPure(state,kind,terms.digest);if(next.terminal==='DENY')return human('EXIT IKANT non ha effetto perché iKant non risulta ACTIVE.');appendEvent('EXIT',next.state,'Human requested exact iKant exit.');return human('Modalità iKant chiusa. Per rientrare serve una nuova accettazione esatta dei Terms correnti.');}
if(kind==='PREFERENCE'){const next=transitionPure(state,kind,terms.digest);if(next.terminal==='DENY')return human('Preferenza non registrata: iKant non è ACTIVE.');next.state.preference=input.slice('PREFER '.length);appendEvent('PREFERENCE',next.state,'Explicit reversible verbosity preference updated.');return human(`Preferenza esplicita impostata su ${next.state.preference}.`);}
if(state.status!=='ACTIVE'){if(!state.admission.terms_presented){state=preservePendingIntent(state,input);state=presentTermsState(state,terms.digest);appendEvent('PENDING_INTENT',state,'The first substantive request is preserved while admission pauses execution.',{pending_intent_sha256:state.admission.pending_intent_sha256});appendEvent('TERMS_PRESENTED',state,'Current Terms were presented and pre-accept repository acquisition is now frozen.',{terms_digest:terms.digest});return human(termsMessage(terms));}if(!state.admission.pending_intent){state=preservePendingIntent(state,input);appendEvent('PENDING_INTENT',state,'A substantive request was preserved while awaiting exact acceptance.',{pending_intent_sha256:state.admission.pending_intent_sha256});}return human('I Terms correnti sono già stati presentati. Per continuare nella stessa sessione rispondi esattamente: I ACCEPT');}
const r=processActiveTurn(state,input,{candidate,hostEngine,resourceGrants,hostObservations,actionReceipt,postActionObservations},terms,dispatch);return r.out;});}

